CREATE OR REPLACE FUNCTION public.tg_checkout(p_tg_id bigint) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.tg_cart%ROWTYPE; s public.app_settings%ROWTYPE; k jsonb; p jsonb; r public.tg_orders%ROWTYPE; result jsonb := '[]'::jsonb; BEGIN SELECT * INTO c FROM public.tg_cart WHERE tg_id=p_tg_id FOR UPDATE; SELECT * INTO s FROM public.app_settings WHERE id=1; IF c.tg_id IS NULL OR jsonb_typeof(c.items) <> 'array' OR jsonb_array_length(c.items)=0 THEN RETURN result; END IF; IF NOT EXISTS(SELECT 1 FROM public.tg_users WHERE tg_id=p_tg_id AND NOT banned) OR trim(s.tg_contact)='' THEN RAISE EXCEPTION 'Checkout unavailable'; END IF; FOR k IN SELECT value FROM jsonb_array_elements(c.items) LOOP SELECT value INTO p FROM jsonb_array_elements(s.tg_plans) WHERE value->>'plan'=k#>>'{}' LIMIT 1; IF p IS NULL OR p->>'plan' NOT IN ('plus','pro','ultra') THEN RAISE EXCEPTION 'Invalid plan'; END IF; INSERT INTO public.tg_orders(tg_id,plan,label,price,method,status) VALUES(p_tg_id,p->>'plan',p->>'label',p->>'price','contact','pending') RETURNING * INTO r; result:=result||jsonb_build_array(jsonb_build_object('id',r.id,'label',r.label)); END LOOP; UPDATE public.tg_cart SET items='[]'::jsonb,updated_at=now() WHERE tg_id=p_tg_id; RETURN result; END; $$;
REVOKE ALL ON FUNCTION public.tg_checkout(bigint) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.tg_checkout(bigint) TO service_role;
CREATE OR REPLACE FUNCTION public.tg_order_action(p_id uuid,p_action text,p_days integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.tg_orders%ROWTYPE; c text; BEGIN SELECT * INTO o FROM public.tg_orders WHERE id=p_id FOR UPDATE; IF o.id IS NULL THEN RAISE EXCEPTION 'Order missing'; END IF; IF p_action NOT IN ('confirm','cancel') THEN RAISE EXCEPTION 'Invalid action'; END IF; IF o.status='paid' AND p_action='confirm' THEN RETURN jsonb_build_object('tg_id',o.tg_id,'code',o.gift_code,'changed',false); END IF; IF o.status <> 'pending' THEN RAISE EXCEPTION 'Order already processed'; END IF; IF p_action='confirm' THEN IF o.method <> 'contact' OR o.plan NOT IN ('plus','pro','ultra') OR p_days < 1 OR p_days > 3650 THEN RAISE EXCEPTION 'Invalid fulfillment'; END IF; c:='WORM-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12)); INSERT INTO public.gift_codes(code,plan,days,max_uses) VALUES(c,o.plan,p_days,1); UPDATE public.tg_orders SET status='paid',gift_code=c,paid_at=now() WHERE id=p_id; UPDATE public.tg_users SET paid=true WHERE tg_id=o.tg_id; ELSE UPDATE public.tg_orders SET status='cancelled' WHERE id=p_id; END IF; INSERT INTO public.tg_bot_log(admin_tg_id,action,detail) VALUES(0,'web_admin_order_'||p_action,p_id::text); RETURN jsonb_build_object('tg_id',o.tg_id,'code',c,'changed',true); END; $$;
REVOKE ALL ON FUNCTION public.tg_order_action(uuid,text,integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.tg_order_action(uuid,text,integer) TO service_role;